-- Atualização das ONGs: rode este arquivo uma vez no SQL Editor do Supabase.
-- Adiciona os campos novos (tipo, formas de apoio, horário, necessidades)
-- e atualiza/insere os dados de exemplo. Pode rodar de novo sem problema.

alter table public.places add column if not exists tipo_org text;
alter table public.places add column if not exists formas_apoio text[];
alter table public.places add column if not exists horario text;
alter table public.places add column if not exists necessidades text;
alter table public.places drop constraint if exists places_tipo_org_check;
alter table public.places add constraint places_tipo_org_check check (tipo_org is null or tipo_org in ('ong', 'protetor'));

on conflict (id) do update set categoria = excluded.categoria, nome = excluded.nome, descricao = excluded.descricao, endereco = excluded.endereco, telefone = excluded.telefone, latitude = excluded.latitude, longitude = excluded.longitude, data_inicio = excluded.data_inicio, data_fim = excluded.data_fim, gratuito = excluded.gratuito, tipo_org = excluded.tipo_org, formas_apoio = excluded.formas_apoio, horario = excluded.horario, necessidades = excluded.necessidades;
